/* Fuentes decorativas de facturas (extraídas de Administrador Emprendedor). No editar a mano. */
const FONT_B64_INTER="";
const FONT_B64_NUNITOSANS="";
const FONT_B64_MONTSERRAT="";
const FONT_B64_PERFECTLEMONADE="";
const FONT_B64_SWEETBLISS="";
const FONT_B64_SHORTCAKESTRAWBERRY="";
const FONT_B64_MOCHIBOP="";

function registerCustomFonts(doc){
  const CUSTOM_FONTS=[
    {key:'Inter',file:'Inter-sub.ttf',b64:FONT_B64_INTER},
    {key:'NunitoSans',file:'NunitoSans-sub.ttf',b64:FONT_B64_NUNITOSANS},
    {key:'Montserrat',file:'Montserrat-sub.ttf',b64:FONT_B64_MONTSERRAT},
    {key:'PerfectLemonade',file:'PerfectLemonade-sub.ttf',b64:FONT_B64_PERFECTLEMONADE},
    {key:'Sweetbliss',file:'Sweetbliss-sub.ttf',b64:FONT_B64_SWEETBLISS},
    {key:'ShortcakeStrawberry',file:'ShortcakeStrawberry-sub.ttf',b64:FONT_B64_SHORTCAKESTRAWBERRY},
    {key:'Mochibop',file:'Mochibop-sub.ttf',b64:FONT_B64_MOCHIBOP}
  ];
  CUSTOM_FONTS.forEach(f=>{
    try{
      doc.addFileToVFS(f.file,f.b64);
      doc.addFont(f.file,f.key,'normal');
      doc.addFont(f.file,f.key,'bold');
      doc.addFont(f.file,f.key,'italic');
      doc.addFont(f.file,f.key,'bolditalic');
    }catch(e){console.error('No se pudo incrustar la fuente',f.key,e)}
  });
}
function fontHasGlyph(doc,family,codePoint){
  try{
    doc.setFont(family,'normal');
    const f=doc.getFont();
    const codeMap=f&&f.metadata&&f.metadata.cmap&&f.metadata.cmap.unicode&&f.metadata.cmap.unicode.codeMap;
    if(!codeMap)return true; // sin datos de glifos (fuente estándar) => se asume compatible, no se modifica el texto
    return !!codeMap[codePoint];
  }catch(e){return true}
}
function nTildeFallback(doc,family){
  return {lower:fontHasGlyph(doc,family,0xf1),upper:fontHasGlyph(doc,family,0xd1)};
}
function applyNTildeFallback(text,support){
  if(text==null)return text;
  let out=String(text);
  if(!support.lower)out=out.replace(/ñ/g,'n');
  if(!support.upper)out=out.replace(/Ñ/g,'N');
  return out;
}
